import json, pathlib, re, collections
manifest='/mnt/data/LSF/results/court/agentic_rule_full_data_gpt54mini_adaptive/all_docs/q04_which_district_judges_presided_over_the_case_below.manifest.json'
with open(manifest) as f:
    data=json.load(f)
if isinstance(data, dict):
    docs=data.get('docs') or data.get('documents') or data.get('items') or data
else:
    docs=data
if isinstance(docs, dict):
    docs=[{'doc_name':k, **v} if isinstance(v, dict) else {'doc_name':k, 'doc_path':v} for k,v in docs.items()]

# judge line patterns across a few lines
line_pats = [
    re.compile(r'"'^(?:Hon'"\\.?\\s*)?(?P<name>.+?)\\s*,\\s*(?:(?:United States\\s+|U\\.S\\.\\s+)?(?:Chief|Senior)\\s+)?(?:United States\\s+|U\\.S\\.\\s+)?District Judge(?:,\\s*|\\s+)Presiding\\s*[\\.\\*\\u2020]*\\s*"'$'"', re.I),
    re.compile(r'"'^(?:Hon'"\\.?\\s*)?(?P<name>.+?)\\s*,\\s*(?:United States\\s+|U\\.S\\.\\s+)?Magistrate Judge(?:,\\s*|\\s+)Presiding\\s*[\\.\\*\\u2020]*\\s*"'$'"', re.I),
]

def extract_judge(lines):
    for i,line in enumerate(lines[:40]):
        t=' '.join(line.split())
        for pat in line_pats:
            m=pat.match(t)
            if m:
                return m.group('name').strip()
        # split presiding line
        if 'presiding' in t.lower() and i>0:
            prev=' '.join(lines[i-1].split())
            cand=f'{prev} {t}'
            for pat in line_pats:
                m=pat.match(cand)
                if m:
                    return m.group('name').strip()
    return None

# parse first initials after case number prefix in D.C. No. line
case_suffix = re.compile(r'\\d+:\\d+-cv-\\d+[A-Z]*-?([A-Z]{1,4})')

map_counts=collections.Counter()
for d in docs:
    text=pathlib.Path(d['doc_path']).read_text(errors='replace')
    lines=text.splitlines()
    judge=extract_judge(lines)
